<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;
class Webhook extends Model {use SoftDeletes;public const EVENT_TYPES=['automation.failed','provisioning.failed','provisioning.expired','firmware.delivery_unavailable'];protected $fillable=['organization_id','name','url','enabled','event_types','signing_secret','secret_prefix','created_by','last_delivery_at','approved_revision_id','approved_submission_id'];protected $hidden=['signing_secret'];protected $casts=['enabled'=>'boolean','event_types'=>'array','signing_secret'=>'encrypted','last_delivery_at'=>'datetime'];public function organization(){return $this->belongsTo(Organization::class);}public function creator(){return $this->belongsTo(User::class,'created_by');}public function deliveries(){return $this->hasMany(WebhookDelivery::class);}public function approvedRevision(){return $this->belongsTo(ResourceRevision::class,'approved_revision_id');}public function approvedSubmission(){return $this->belongsTo(ResourcePublicationSubmission::class,'approved_submission_id');}public function collaborators(){return $this->hasMany(ResourceCollaborator::class,'resource_id')->where('resource_type','webhook');} }
